    "notes": "Das neutral gesprochene 过 (guo) steht direkt hinter dem Verb und drückt aus, dass man etwas irgendwann schon einmal erlebt oder getan hat: 我去过中国 „ich war schon einmal in China“. Verneint wird mit 没(有), 过 bleibt dabei stehen: 我没吃过 „das habe ich noch nie gegessen“. Anders als 了 (le), das eine konkrete, abgeschlossene Handlung meldet, betont 过 die Erfahrung; Fragen lauten meist …过…吗? oder …过没有? Deutsche sagen hier oft „schon mal“ oder „noch nie“.",
